import numpy as np
import pandas as pd
from sklearn.base import BaseEstimator, TransformerMixin
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import StandardScaler

class FeatureSelector(BaseEstimator, TransformerMixin):
    def __init__(self, columns):
        self.columns = columns

    def fit(self, X, y=None):
        return self

    def transform(self, X):
        if isinstance(X, pd.DataFrame):
            return X[self.columns].values
        return X[:, self.columns]

class LogTransformer(BaseEstimator, TransformerMixin):
    def __init__(self, columns=None):
        self.columns = columns

    def fit(self, X, y=None):
        return self

    def transform(self, X):
        X = X.copy()
        if self.columns is None:
            return np.log1p(np.abs(X))
        for col in self.columns:
            X[:, col] = np.log1p(np.abs(X[:, col]))
        return X

class BinningTransformer(BaseEstimator, TransformerMixin):
    def __init__(self, columns, n_bins=5):
        self.columns = columns
        self.n_bins = n_bins

    def fit(self, X, y=None):
        self.bin_edges_ = {}
        for col in self.columns:
            self.bin_edges_[col] = np.linspace(
                X[:, col].min(), X[:, col].max(), self.n_bins + 1
            )
        return self

    def transform(self, X):
        X = X.copy()
        for col in self.columns:
            X[:, col] = np.digitize(X[:, col], self.bin_edges_[col]) - 1
        return X

class InteractionFeatures(BaseEstimator, TransformerMixin):
    def __init__(self, pairs):
        self.pairs = pairs

    def fit(self, X, y=None):
        return self

    def transform(self, X):
        interactions = np.column_stack([
            X[:, i] * X[:, j] for i, j in self.pairs
        ])
        return np.hstack([X, interactions])

# Test custom transformers
np.random.seed(42)
X = np.random.randn(100, 5)

pipeline = Pipeline([
    ('select', FeatureSelector(columns=[0, 1, 2])),
    ('log', LogTransformer(columns=[0, 1])),
    ('interact', InteractionFeatures(pairs=[(0, 1), (1, 2)])),
    ('scale', StandardScaler())
])

X_transformed = pipeline.fit_transform(X)
print(f"Custom Transformer Pipeline:")
print(f"  Input shape: {X.shape}")
print(f"  Output shape: {X_transformed.shape}")
print(f"  Steps: {[name for name, _ in pipeline.steps]}")
